import { createHash } from "node:crypto";
import { QUANTITY_FORMAT, QUANTITY_MAX } from "@/modules/sync-v1/domain/envelope";
import { CallHttpError } from "./call-error";

/** UUID v4 in lowercase, generated by the phone (E2-D10). */
export const OPERATION_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
/** Any server-generated UUID (call ids). */
export const SERVER_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
export const SEQUENCE_MAX = 2_147_483_647;
export const MAX_LINES = 50;

export type OperationKind = "CONFIRM" | "WITHDRAW";

export interface ConfirmInput {
  operation_id: string;
  sequence: number;
  consent?: { version: string; accepted_at: string } | null;
  lines: { product_ref: string; quantity_base: string }[];
}

export interface WithdrawInput {
  operation_id: string;
  sequence: number;
}

/** A farmer operation after the structural checks, before the call is read. */
export interface NormalizedOperation {
  kind: OperationKind;
  operationId: string;
  sequence: number;
  /** Null for a withdrawal, or a confirmation whose consent is absent. */
  consent: { version: string; acceptedAt: Date } | null;
  /** Sorted by product_ref; empty = withdrawal (E2-D8). */
  lines: { productRef: string; quantityBase: bigint }[];
  fingerprint: string;
}

const INVALID = () => new CallHttpError(400, "PAYLOAD_INVALID");

/**
 * E2-D8: `quantity_base` is a decimal string of an integer > 0 in the base
 * unit (ML/G), within int64 as in Sync v1. Anything else in the string is
 * 422 QUANTITY_INVALID.
 */
export function parseQuantity(raw: unknown): bigint {
  if (typeof raw !== "string") throw INVALID();
  if (!QUANTITY_FORMAT.test(raw)) throw new CallHttpError(422, "QUANTITY_INVALID");
  const value = BigInt(raw);
  if (value <= 0n || value > QUANTITY_MAX) throw new CallHttpError(422, "QUANTITY_INVALID");
  return value;
}

function checkEnvelope(operationId: unknown, sequence: unknown): { operationId: string; sequence: number } {
  if (typeof operationId !== "string" || !OPERATION_ID.test(operationId)) throw INVALID();
  if (typeof sequence !== "number" || !Number.isInteger(sequence) || sequence < 1 || sequence > SEQUENCE_MAX) {
    throw INVALID();
  }
  return { operationId, sequence };
}

/**
 * `PUT …/participation`. Lines with the same product twice are 400; an
 * empty list is a withdrawal. The consent is only checked against the call
 * (409 CONSENT_REQUIRED) once the operation is decided under the lock, so an
 * absent or outdated consent is kept as given here.
 */
export function normalizeConfirm(input: ConfirmInput): NormalizedOperation {
  const { operationId, sequence } = checkEnvelope(input.operation_id, input.sequence);
  if (!Array.isArray(input.lines) || input.lines.length > MAX_LINES) throw INVALID();
  const seen = new Set<string>();
  const lines = input.lines.map((line) => {
    if (typeof line?.product_ref !== "string" || line.product_ref.length < 1 || line.product_ref.length > 64) {
      throw INVALID();
    }
    if (seen.has(line.product_ref)) throw INVALID();
    seen.add(line.product_ref);
    return { productRef: line.product_ref, quantityBase: parseQuantity(line.quantity_base) };
  });
  lines.sort((a, b) => (a.productRef < b.productRef ? -1 : a.productRef > b.productRef ? 1 : 0));
  let consent: NormalizedOperation["consent"] = null;
  if (input.consent) {
    const acceptedAt = new Date(input.consent.accepted_at);
    if (typeof input.consent.version !== "string" || Number.isNaN(acceptedAt.getTime())) throw INVALID();
    consent = { version: input.consent.version, acceptedAt };
  }
  const base = { kind: "CONFIRM" as const, operationId, sequence, consent, lines };
  return { ...base, fingerprint: operationFingerprint(base) };
}

/** `POST …/participation/withdraw`. */
export function normalizeWithdraw(input: WithdrawInput): NormalizedOperation {
  const { operationId, sequence } = checkEnvelope(input.operation_id, input.sequence);
  const base = { kind: "WITHDRAW" as const, operationId, sequence, consent: null, lines: [] };
  return { ...base, fingerprint: operationFingerprint(base) };
}

/**
 * E2-D10: SHA-256 of the normalized body (kind, sequence, consent with its
 * date in ISO form, lines sorted by product). The same operation id with
 * another fingerprint is 409 OPERATION_ID_REUSED; key order, the date's
 * spelling or the order of lines do not change it.
 */
export function operationFingerprint(operation: Omit<NormalizedOperation, "fingerprint">): string {
  const canonical = JSON.stringify([
    "E2-OP-1",
    operation.kind,
    operation.operationId,
    operation.sequence,
    operation.consent ? [operation.consent.version, operation.consent.acceptedAt.toISOString()] : null,
    operation.lines.map((line) => [line.productRef, line.quantityBase.toString()]),
  ]);
  return createHash("sha256").update(canonical, "utf8").digest("hex");
}
